import java.io.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import org.apache.commons.text.StringSubstitutor;
import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

@WebServlet("/report")
public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());

    // Template cache for performance
    private static final Map<String, String> TEMPLATES = new HashMap<>();
    static {
        TEMPLATES.put("summary", "SELECT id, name, amount FROM transactions WHERE department = '${dept}' AND fiscal_year = ${year}");
        TEMPLATES.put("detail", "SELECT * FROM transactions WHERE department = '${dept}' AND status = '${status}' ORDER BY ${orderBy}");
        TEMPLATES.put("audit", "SELECT t.*, u.email FROM transactions t JOIN users u ON t.user_id = u.id WHERE t.department = '${dept}' AND t.amount > ${minAmount}");
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {

        String templateName = req.getParameter("template");
        String dept = req.getParameter("dept");
        String year = req.getParameter("year");
        String status = req.getParameter("status");
        String orderBy = req.getParameter("orderBy");
        String minAmount = req.getParameter("minAmount");

        if (templateName == null || !TEMPLATES.containsKey(templateName)) {
            resp.sendError(400, "Invalid template");
            return;
        }

        // Basic input length validation
        if (dept != null && dept.length() > 64) {
            resp.sendError(400, "Department name too long");
            return;
        }

        // Build substitution map from request parameters
        Map<String, String> params = new HashMap<>();
        params.put("dept", dept != null ? dept : "");
        params.put("year", year != null ? year : "2024");
        params.put("status", status != null ? status : "completed");
        params.put("orderBy", orderBy != null ? orderBy : "id");
        params.put("minAmount", minAmount != null ? minAmount : "0");

        // Resolve template with user-supplied values
        StringSubstitutor sub = new StringSubstitutor(params);
        String query = sub.replace(TEMPLATES.get(templateName));

        log.info("Executing report query for dept: " + dept);

        Connection conn = null;
        Statement stmt = null;
        ResultSet rs = null;

        try {
            conn = getConnection();
            stmt = conn.createStatement();
            rs = stmt.executeQuery(query);

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.write(resultSetToJson(rs));

        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        } finally {
            closeQuietly(rs, stmt, conn);
        }
    }

    private Connection getConnection() throws SQLException {
        String url = System.getenv("JDBC_URL");
        String user = System.getenv("DB_USER");
        String pass = System.getenv("DB_PASS");
        return DriverManager.getConnection(url, user, pass);
    }

    private String resultSetToJson(ResultSet rs) throws SQLException {
        StringBuilder sb = new StringBuilder("[");
        ResultSetMetaData meta = rs.getMetaData();
        int cols = meta.getColumnCount();
        boolean first = true;
        while (rs.next()) {
            if (!first) sb.append(",");
            sb.append("{");
            for (int i = 1; i <= cols; i++) {
                if (i > 1) sb.append(",");
                sb.append("\"").append(meta.getColumnName(i)).append("\":");
                sb.append("\"").append(rs.getString(i)).append("\"");
            }
            sb.append("}");
            first = false;
        }
        sb.append("]");
        return sb.toString();
    }

    private void closeQuietly(ResultSet rs, Statement stmt, Connection conn) {
        try { if (rs != null) rs.close(); } catch (Exception e) {}
        try { if (stmt != null) stmt.close(); } catch (Exception e) {}
        try { if (conn != null) conn.close(); } catch (Exception e) {}
    }
}
